
"use client";

import { useEffect, useState } from "react";
import Link from "next/link";

type Producto = {
  id: number;
  documentId: string;
  name: string;
  slug: string;
  description: string;
  price: number;
  stock: number;
  image?: {
    url: string;
    name?: string;
  } | null;
};

export default function Home() {
  const [productos, setProductos] = useState<Producto[]>([]);
  const [cargando, setCargando] = useState(true);
  const [error, setError] = useState("");

  useEffect(() => {
    async function cargarProductos() {
      try {
        const respuesta = await fetch(
          "http://localhost:1337/api/products?populate=image"
        );

        if (!respuesta.ok) {
          throw new Error("No se pudieron cargar los productos.");
        }

        const resultado = await respuesta.json();
        setProductos(resultado.data ?? []);
      } catch (err) {
        console.error(err);
        setError(
          "No se pudieron cargar los productos. Comprueba que Strapi esté funcionando."
        );
      } finally {
        setCargando(false);
      }
    }

    cargarProductos();
  }, []);

  return (
    <main className="min-h-screen bg-gray-950 text-white">
      <header className="border-b border-gray-800 px-6 py-5">
        <div className="mx-auto flex max-w-7xl items-center justify-between">
          <h1 className="text-2xl font-bold">
            Mi Tienda
          </h1>
          <span className="text-sm text-gray-300">
            Catálogo de productos
          </span>
        </div>
      </header>

      <section className="mx-auto max-w-7xl px-6 py-12">
        <div className="mb-10">
          <p className="mb-3 text-sm uppercase tracking-widest text-blue-400">
            Colección disponible
          </p>
          <h2 className="text-4xl font-bold">
            Nuestros productos
          </h2>
          <p className="mt-3 text-gray-400">
            Explora los productos disponibles en nuestra tienda.
          </p>
        </div>

        {cargando && (
          <p className="text-gray-300">Cargando productos...</p>
        )}

        {error && (
          <p className="rounded-lg bg-red-950 p-4 text-red-300">
            {error}
          </p>
        )}

        {!cargando && !error && productos.length === 0 && (
          <p>No hay productos publicados todavía.</p>
        )}

        <div className="grid grid-cols-1 gap-6 sm:grid-cols-2 lg:grid-cols-3">
          {productos.map((producto) => (
            <article
              key={producto.documentId}
              className="rounded-2xl border border-gray-800 bg-gray-900 p-6 transition hover:-translate-y-1 hover:border-blue-500"
            >
              <div className="mb-5 flex h-48 items-center justify-center overflow-hidden rounded-xl bg-gray-800">
  {producto.image?.url ? (
    <img
      src={`http://localhost:1337${producto.image.url}`}
      alt={producto.name}
      className="h-full w-full object-contain"
    />
  ) : (
    <span className="text-5xl">🛍️</span>
  )}
</div>

              <h3 className="text-xl font-semibold">
                {producto.name}
              </h3>

              <p className="mt-2 min-h-12 text-sm text-gray-400">
                {producto.description}
              </p>

              <div className="mt-5 flex items-center justify-between gap-3">
                <span className="text-2xl font-bold text-blue-400">
                  ${producto.price.toFixed(2)}
                </span>
                <span className="text-sm text-gray-400">
                  Stock: {producto.stock}
                </span>
              </div>
            </article>
          ))}
        </div>
      </section>
    </main>
  );
}
